int main() {
    int N, D1, D2;
    scanf("%d %d %d", &N, &D1, &D2);

    int size = 2 * N;
    // We'll assign colors 0 or 1 based on parity pattern
    // that avoids distance sqrt(D1) and sqrt(D2)

    // Create coloring grid
    int color[size][size];
    for (int i = 0; i < size; i++)
        for (int j = 0; j < size; j++)
            color[i][j] = 0;

    // Determine pattern for D1
    int d1_pattern = 0;
    if (D1 % 2 == 0) {
        // Check representation as sum of two squares
        int found = 0;
        for (int a = 0; a * a <= D1 && !found; a++) {
            int b2 = D1 - a * a;
            int b = 0;
            while (b * b < b2) b++;
            if (b * b == b2) {
                found = 1;
                if ((a % 2) != (b % 2)) d1_pattern = 1;
            }
        }
    } else {
        d1_pattern = 1;
    }

    int d2_pattern = 0;
    if (D2 % 2 == 0) {
        int found = 0;
        for (int a = 0; a * a <= D2 && !found; a++) {
            int b2 = D2 - a * a;
            int b = 0;
            while (b * b < b2) b++;
            if (b * b == b2) {
                found = 1;
                if ((a % 2) != (b % 2)) d2_pattern = 1;
            }
        }
    } else {
        d2_pattern = 1;
    }

    // Assign colors
    for (int i = 0; i < size; i++) {
        for (int j = 0; j < size; j++) {
            int c = ((i / (d1_pattern ? 1 : 2)) + (j / (d1_pattern ? 1 : 2))) % 2;
            c = c * 2 + ((i / (d2_pattern ? 1 : 2)) + (j / (d2_pattern ? 1 : 2))) % 2;
            color[i][j] = c;
        }
    }

    // Count and output all points of the most frequent color
    int count[4] = {0};
    for (int i = 0; i < size; i++)
        for (int j = 0; j < size; j++)
            count[color[i][j]]++;

    int best = 0;
    for (int k = 1; k < 4; k++)
        if (count[k] > count[best]) best = k;

    int printed = 0;
    for (int i = 0; i < size && printed < N * N; i++) {
        for (int j = 0; j < size && printed < N * N; j++) {
            if (color[i][j] == best) {
                printf("%d %d\n", i, j);
                printed++;
            }
        }
    }

    return 0;
}

