int main(void) {
    int N;
    long long D1, D2;
    if (scanf("%d %lld %lld", &N, &D1, &D2) != 3) return 0;

    int M = 2 * N;
    int total = M * M;

    int *color = (int *)malloc(sizeof(int) * total);
    if (!color) return 0;

    /* 
       For a distance constraint d:
       If d is odd, parity of x+y flips across edges of squared distance d.
       If d is even, divide by 2 repeatedly until odd; then parity of x (equiv. y) flips.
       This gives a valid 2-coloring where any forbidden edge connects opposite colors.
    */
    long long ds[2] = {D1, D2};

    for (int y = 0; y < M; y++) {
        for (int x = 0; x < M; x++) {
            int c = 0;
            for (int k = 0; k < 2; k++) {
                long long d = ds[k];
                while ((d & 1LL) == 0) d >>= 1;
                int bit;
                if (d & 1LL) {
                    /* original reduced d is odd */
                    /* if no division happened, use parity of x+y; otherwise parity of x */
                    long long tmp = ds[k];
                    if (tmp & 1LL) bit = (x + y) & 1;
                    else bit = x & 1;
                } else {
                    bit = x & 1; /* unreachable */
                }
                c |= bit << k;
            }
            color[y * M + x] = c;
        }
    }

    int cnt[4] = {0, 0, 0, 0};
    for (int i = 0; i < total; i++) cnt[color[i]]++;

    int target = N * N;
    int pick = 0;
    for (int c = 0; c < 4; c++) {
        if (cnt[c] >= target) {
            pick = c;
            break;
        }
    }

    int printed = 0;
    for (int y = 0; y < M && printed < target; y++) {
        for (int x = 0; x < M && printed < target; x++) {
            if (color[y * M + x] == pick) {
                printf("%d %d\n", x, y);
                printed++;
            }
        }
    }

    free(color);
    return 0;
}

