using ll = long long;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    ll D1, D2;
    cin >> N >> D1 >> D2;

    int M = 2 * N;

    auto build_color = [&](ll D) {
        // color[x][y] in {0,1}
        vector<vector<int>> color(M, vector<int>(M, 0));

        // Find all integer vectors (dx,dy) with dx^2 + dy^2 = D
        vector<pair<int,int>> moves;
        for (ll dx = 0; dx * dx <= D; dx++) {
            ll rem = D - dx * dx;
            ll dy = sqrt((long double)rem);
            while ((dy + 1) * (dy + 1) <= rem) dy++;
            while (dy * dy > rem) dy--;
            if (dy * dy == rem) {
                int x = (int)dx, y = (int)dy;
                vector<pair<int,int>> cand = {
                    { x,  y}, { x, -y}, {-x,  y}, {-x, -y},
                    { y,  x}, { y, -x}, {-y,  x}, {-y, -x}
                };
                for (auto &p : cand) moves.push_back(p);
            }
        }
        sort(moves.begin(), moves.end());
        moves.erase(unique(moves.begin(), moves.end()), moves.end());

        // BFS 2-coloring on the graph of points in [0,M)^2,
        // edges connect pairs at squared distance D.
        for (int sx = 0; sx < M; sx++) {
            for (int sy = 0; sy < M; sy++) {
                if (color[sx][sy] != 0) continue;
                queue<pair<int,int>> q;
                color[sx][sy] = 1;
                q.push({sx, sy});
                while (!q.empty()) {
                    auto [x, y] = q.front();
                    q.pop();
                    for (auto [dx, dy] : moves) {
                        int nx = x + dx, ny = y + dy;
                        if (0 <= nx && nx < M && 0 <= ny && ny < M) {
                            if (color[nx][ny] == 0) {
                                color[nx][ny] = 3 - color[x][y];
                                q.push({nx, ny});
                            }
                        }
                    }
                }
            }
        }

        // convert to 0/1
        for (int i = 0; i < M; i++) {
            for (int j = 0; j < M; j++) color[i][j]--;
        }
        return color;
    };

    auto c1 = build_color(D1);
    auto c2 = build_color(D2);

    vector<pair<int,int>> groups[4];
    for (int i = 0; i < M; i++) {
        for (int j = 0; j < M; j++) {
            int id = c1[i][j] * 2 + c2[i][j];
            groups[id].push_back({i, j});
        }
    }

    for (int k = 0; k < 4; k++) {
        if ((int)groups[k].size() >= N * N) {
            for (int i = 0; i < N * N; i++) {
                cout << groups[k][i].first << ' ' << groups[k][i].second << '\n';
            }
            return 0;
        }
    }

    return 0;
}

