        // Determine parity pattern based on D1 and D2
        int[][] pattern1 = createPattern(D1);
        int[][] pattern2 = createPattern(D2);

        int size = 2 * N;
        List<int[]> ans = new ArrayList<>();
        for (int i = 0; i < size && ans.size() < N * N; i++) {
            for (int j = 0; j < size && ans.size() < N * N; j++) {
                if (pattern1[i % pattern1.length][j % pattern1[0].length] == 0 &&
                    pattern2[i % pattern2.length][j % pattern2[0].length] == 0) {
                    ans.add(new int[]{i, j});
                }
            }
        }

        for (int[] p : ans) {
            System.out.println(p[0] + " " + p[1]);
        }
    }

    static int[][] createPattern(int D) {
        // Find the smallest square tiling that avoids distance sqrt(D)
        // We use the property: (x^2 + y^2) % D grouping
        int g = gcd(D, 1); // just placeholder
        int mod = 1;
        while (true) {
            boolean ok = true;
            for (int x = 0; x < mod; x++) {
                for (int y = 0; y < mod; y++) {
                    for (int dx = 0; dx < mod; dx++) {
                        for (int dy = 0; dy < mod; dy++) {
                            if (x == dx && y == dy) continue;
                            int dist = (x - dx) * (x - dx) + (y - dy) * (y - dy);
                            if (dist == D) {
                                ok = false;
                                break;
                            }
                        }
                        if (!ok) break;
                    }
                    if (!ok) break;
                }
                if (!ok) break;
            }
            if (ok) break;
            mod++;
        }

        int[][] pat = new int[mod][mod];
        // Try to assign 0/1 so no two 0's are distance sqrt(D) apart
        // We'll do a greedy fill
        for (int i = 0; i < mod; i++) {
            for (int j = 0; j < mod; j++) {
                boolean canZero = true;
                for (int di = -mod; di <= mod; di++) {
                    for (int dj = -mod; dj <= mod; dj++) {
                        if (di == 0 && dj == 0) continue;
                        int ni = i + di;
                        int nj = j + dj;
                        if (ni >= 0 && ni < mod && nj >= 0 && nj < mod && pat[ni][nj] == 0) {
                            int dist = di * di + dj * dj;
                            if (dist == D) {
                                canZero = false;
                                break;
                            }
                        }
                    }
                    if (!canZero) break;
                }
                if (canZero) pat[i][j] = 0;
                else pat[i][j] = 1;
            }
        }
        return pat;
    }

    static int gcd(int a, int b) {
        while (b != 0) {
            int t = b;
            b = a % b;
            a = t;
        }
        return a;
    }
}

