import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do c = read(); while (c <= ' ' && c != -1);
            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }

    static int N;
    static long D1, D2;
    static int SIZE;

    static int[][] buildColor(long D) {
        int[][] color = new int[SIZE][SIZE];

        ArrayList<int[]> moves = new ArrayList<>();
        long lim = (long) Math.sqrt(D);
        for (long dx = 0; dx <= lim; dx++) {
            long rem = D - dx * dx;
            if (rem < 0) continue;
            long dy = (long) Math.sqrt(rem);
            if (dy * dy != rem) continue;

            int x = (int) dx;
            int y = (int) dy;

            int[] sx = (x == 0) ? new int[]{0} : new int[]{x, -x};
            int[] sy = (y == 0) ? new int[]{0} : new int[]{y, -y};

            for (int a : sx) {
                for (int b : sy) {
                    if (a == 0 && b == 0) continue;
                    moves.add(new int[]{a, b});
                }
            }
        }

        ArrayDeque<int[]> q = new ArrayDeque<>();
        for (int i = 0; i < SIZE; i++) {
            Arrays.fill(color[i], -1);
        }

        for (int si = 0; si < SIZE; si++) {
            for (int sj = 0; sj < SIZE; sj++) {
                if (color[si][sj] != -1) continue;
                color[si][sj] = 0;
                q.add(new int[]{si, sj});

                while (!q.isEmpty()) {
                    int[] cur = q.poll();
                    int x = cur[0], y = cur[1];
                    int c = color[x][y];
                    for (int[] mv : moves) {
                        int nx = x + mv[0];
                        int ny = y + mv[1];
                        if (0 <= nx && nx < SIZE && 0 <= ny && ny < SIZE) {
                            if (color[nx][ny] == -1) {
                                color[nx][ny] = c ^ 1;
                                q.add(new int[]{nx, ny});
                            }
                        }
                    }
                }
            }
        }

        return color;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        N = fs.nextInt();
        D1 = fs.nextLong();
        D2 = fs.nextLong();

        SIZE = 2 * N;

        int[][] c1 = buildColor(D1);
        int[][] c2 = buildColor(D2);

        ArrayList<int[]>[][] groups = new ArrayList[2][2];
        for (int a = 0; a < 2; a++) {
            for (int b = 0; b < 2; b++) {
                groups[a][b] = new ArrayList<>();
            }
        }

        for (int i = 0; i < SIZE; i++) {
            for (int j = 0; j < SIZE; j++) {
                groups[c1[i][j]][c2[i][j]].add(new int[]{i, j});
            }
        }

        ArrayList<int[]> ans = null;
        for (int a = 0; a < 2; a++) {
            for (int b = 0; b < 2; b++) {
                if (groups[a][b].size() >= N * N) {
                    ans = groups[a][b];
                    break;
                }
            }
            if (ans != null) break;
        }

        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < N * N; i++) {
            int[] p = ans.get(i);
            sb.append(p[0]).append(' ').append(p[1]).append('\n');
        }
        System.out.print(sb.toString());
    }
}
